"""Generate the buildless GitHub Pages edition from the reviewed content file."""
import json
from pathlib import Path
from html import escape as h
ROOT=Path(__file__).resolve().parents[1]
d=json.loads((ROOT/'content.json').read_text())
N=sum(len(e['events']) for e in d['eras'])
def link(k):
 label,url=d['sources'][k]
 return f'<a href="{h(url,quote=True)}" target="_blank" rel="noopener noreferrer">{h(label)} <span aria-hidden="true">↗</span></a>'
def nav(cls=''):
 return ''.join(f'<a class="era-link {cls}" href="#{e["id"]}" data-era="{e["id"]}"><span class="nav-number">{e["number"]}</span><span>{h(e["short"])}<small>{h(e["range"])}</small></span><span aria-hidden="true">↗</span></a>' for e in d['eras'])
events_by_id={event[2]:event for era in d['eras'] for event in era['events']}
def related_links(slug):
 related=d.get('related',{}).get(slug,[])
 if not related:return ''
 links=''.join(f'<li><a href="#{h(key)}">{h(events_by_id[key][0])} · {h(events_by_id[key][3])} <span aria-hidden="true">→</span></a></li>' for key in related)
 return f'<div class="event-evidence"><span class="eyebrow">Read alongside</span><ul>{links}</ul></div>'
def chapter(e):
 items=[]
 for j,(year,date,slug,title,topic,body,context,refs) in enumerate(e['events']):
  search=' '.join([year,title,topic,body,context]).lower()
  items.append(f'''<details class="event" id="{slug}" data-topic="{topic}" data-search="{h(search,quote=True)}" {'open' if j==0 else ''}>
  <summary><span class="event-date">{h(year)}</span><span class="event-heading"><span class="topic">{topic}</span><span class="event-title">{h(title)}</span></span><span class="event-plus" aria-hidden="true"></span></summary>
  <div class="event-body"><p>{h(body)}</p><h4>Context & significance</h4><p>{h(context)}</p><div class="event-evidence"><span class="eyebrow">Read the record</span><ul>{''.join('<li>'+link(r)+'</li>' for r in refs)}</ul><a class="permalink" href="#{slug}">Link to this event <span aria-hidden="true">↗</span></a></div>{related_links(slug)}</div>
  </details>''')
 return f'''<section class="era" id="{e['id']}" aria-labelledby="heading-{e['id']}"><div class="chapter-meta"><span>Chapter {e['number']}</span><span>{h(e['range'])}</span></div><h2 id="heading-{e['id']}">{h(e['title'])}</h2><p class="chapter-question">{h(e['question'])}</p><p class="chapter-intro">{h(e['intro'])}</p><aside class="context-note"><span>Keep in view</span><p>{h(e['tension'])}</p></aside><div class="events">{''.join(items)}</div></section>'''
wheel=''.join(f'<line x1="160" y1="160" x2="160" y2="32" transform="rotate({i*15} 160 160)"/>' for i in range(24))
chapters=''.join(chapter(e) for e in d['eras'])
html=f'''<!doctype html>
<html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="theme-color" content="#101713"><title>India By Era | A history of independent India</title><meta name="description" content="Explore independent India through six eras. A chronological, source-linked history of democracy, the economy, conflict, science and society, from 1947 onward."><link rel="canonical" href="https://ashish-bhatia.github.io/IndiaByEra/"><meta property="og:title" content="India By Era"><meta property="og:description" content="A republic. Still in the making. Explore independent India through six eras."><meta property="og:type" content="website"><meta property="og:url" content="https://ashish-bhatia.github.io/IndiaByEra/"><link rel="icon" href="assets/favicon.svg" type="image/svg+xml"><link rel="stylesheet" href="assets/style.css"><script src="assets/app.js" defer></script></head>
<body><a class="skip" href="#reader">Skip to the history</a><div class="reading-progress" aria-hidden="true"><span id="progress"></span></div>
<header class="site-header"><a class="brand" href="#top" aria-label="India By Era home"><span class="brand-symbol" aria-hidden="true">i</span>INDIA BY ERA<span class="brand-period">.</span></a><nav class="top-nav" aria-label="Main navigation"><a href="#reader" data-view="all">The timeline</a><a href="#connections">Connections</a><a href="#sources">Sources & approach</a></nav><button id="menu-toggle" class="menu-toggle" aria-expanded="false" aria-controls="menu">Menu <span aria-hidden="true">☰</span></button></header>
<div id="menu" class="menu" hidden><nav aria-label="Chapter menu">{nav()}<a href="#reader" data-view="all">Full timeline ↗</a><a href="#connections">Connections ↗</a><a href="#sources">Sources & approach ↗</a></nav></div>
<main id="top"><section class="hero" aria-labelledby="hero-title"><div class="hero-main"><p class="eyebrow"><span class="live-dot"></span> A history of independent India · 1947 onward</p><h1 id="hero-title">A republic.<br>Still in the <em>making.</em></h1><p class="hero-deck">The choices, conflicts and breakthroughs that shaped modern India. Follow the story, one era at a time.</p><a class="primary-link" href="#foundations">Begin in 1947 <span aria-hidden="true">↗</span></a><a class="secondary-link" href="#reader" data-view="all">Browse the full timeline <span aria-hidden="true">→</span></a></div><div class="hero-art" aria-hidden="true"><span class="art-caption">INDEPENDENCE / CONTINUITY / CHANGE</span><svg viewBox="0 0 320 320" fill="none"><circle cx="160" cy="160" r="151" stroke-dasharray="1 8"/><circle cx="160" cy="160" r="128"/><circle cx="160" cy="160" r="134"/>{wheel}<circle cx="160" cy="160" r="24"/><circle cx="160" cy="160" r="7" fill="currentColor"/></svg><span class="art-year">1947<span>→</span></span><span class="art-end">AN UNFINISHED STORY</span></div></section>
<section class="era-index" aria-labelledby="index-title"><div class="section-label"><h2 id="index-title">Six eras. One continuing story.</h2><span>{N} selected milestones</span></div><div class="era-strip">{''.join(f'<a href="#{e["id"]}"><span class="strip-number">{e["number"]}</span><strong>{h(e["range"])}</strong><span>{h(e["short"])} <b aria-hidden="true">↗</b></span></a>' for e in d['eras'])}</div></section>
<section class="reading-layout" id="reader" aria-label="Explore the history"><aside class="sidebar"><div class="sidebar-inner"><span class="eyebrow">The chapters</span><nav aria-label="Choose an era">{nav()}</nav><a class="all-link" href="#reader" data-view="all">View the full timeline →</a><p class="sidebar-note">Dates tell you when.<br>Context helps explain why.</p></div></aside><div class="reader-main"><div class="reader-toolbar"><div class="search-wrap"><label class="sr-only" for="search">Search events, years and people</label><span aria-hidden="true">⌕</span><input id="search" type="search" placeholder="Search a year, event or person…" autocomplete="off"></div><label class="sr-only" for="topic">Filter by topic</label><select id="topic"><option value="all">All topics</option>{''.join(f'<option>{t}</option>' for t in ['Democracy','Economy','Society','Environment','Conflict','Science','Culture'])}</select></div><div class="reader-status"><p id="result-status" role="status" aria-live="polite">{N} milestones across six eras</p><div class="reader-actions"><button id="reset" hidden>Reset</button><button id="expand">Expand stories <span aria-hidden="true">+</span></button></div></div><noscript><p class="noscript">All chapters are available below. Search and filters require JavaScript.</p></noscript><p id="empty" class="empty" hidden>No events match your search. Try a year, a name or another topic.</p><div id="chapters">{chapters}</div><nav id="chapter-pager" class="chapter-pager" aria-label="Continue reading" hidden><a id="previous" href="#foundations">← Previous era</a><a id="next" href="#food-and-war">Next era →</a></nav></div></section>
<section id="connections" class="connections" aria-labelledby="connections-title"><div><p class="eyebrow">Across the chapters</p><h2 id="connections-title">Change rarely starts<br>from zero.</h2><p>Follow three threads across different governments and generations. Select an event to return to its place in the story.</p></div><div class="connection-tracks"><article><h3>From planning to markets</h3><ol><li><a href="#first-plan"><span>1951</span>Five-Year Plans</a></li><li><a href="#liberalisation"><span>1991</span>Economic reform</a></li><li><a href="#pli"><span>2020–21</span>Manufacturing incentives</a></li></ol></article><article><h3>Institutions, rights, accountability</h3><ol><li><a href="#republic"><span>1950</span>The republic</a></li><li><a href="#emergency"><span>1975</span>The Emergency</a></li><li><a href="#rti"><span>2005</span>Right to Information</a></li></ol></article><article><h3>A longer technology story</h3><ol><li><a href="#cdot"><span>1984</span>Telecom research</a></li><li><a href="#aadhaar"><span>2010</span>First Aadhaar</a></li><li><a href="#upi"><span>2016</span>UPI pilot</a></li></ol></article><p class="track-note">Selected chronological connections. These sequences do not imply that one event alone caused the next.</p></div></section>
<section id="sources" class="sources" aria-labelledby="sources-title"><p class="eyebrow">Go beyond the headline</p><h2 id="sources-title">History with a paper trail.</h2><div class="method-grid"><div><h3>What this edition covers</h3><p>{h(d['coverage'])}</p><p>The six eras are editorial groupings, not official historical categories. Boundary years overlap when a transition crosses governments or institutions.</p></div><div><h3>How to read the stories</h3><p>Each event separates a short factual account from context and significance. The latter includes editorial interpretation. Source links sit inside each expanded story.</p><p>Institutional records help establish dates, decisions and programme design. They do not, by themselves, establish every claimed policy outcome.</p></div><div><h3>What to keep questioning</h3><p>National milestones do not capture every regional, social or personal experience. This is a starting point for further reading, not a ranking of prime ministers or a verdict on any party.</p><p>Editorial review: {h(d['reviewed'])}. Review date does not imply complete coverage up to that date.</p></div></div><details class="source-directory"><summary>Open the source directory <span>{len(d['sources'])} references</span></summary><ol>{''.join('<li>'+link(k)+'</li>' for k in d['sources'])}</ol></details></section></main>
<footer><a class="footer-brand" href="#top">India By Era.</a><p>Read the past. Question the present.</p><a href="#top">Back to top ↑</a></footer></body></html>'''
(ROOT/'index.html').write_text(html)
print(f'Built {N} milestones across {len(d["eras"])} eras, with {len(d["sources"])} references.')
